#ifndef  _STM32_H
#define  _STM32_H

#include "stm32_parms.H"
#include "systemc.h"
#include "ac_module.H"
#include "ac_utils.H"
#include "stm32_arch.H"
#include "stm32_isa.H"
#include "stm32_syscall.H"


class stm32: public ac_module, public stm32_arch {
private:
  typedef struct {
    uint8_t op;
    uint8_t subop1;
    uint8_t rd1;
    uint8_t imm1;
  } T_Type_Imm8;

  typedef struct {
    uint8_t op;
    uint8_t subop2;
    uint8_t rm2;
    uint8_t rn2;
    uint8_t rd2;
  } T_Type_Alu3;

  typedef struct {
    uint8_t op;
    uint8_t subop3;
    uint8_t rm3;
    uint8_t rdn3;
  } T_Type_Alu2;

  typedef struct {
    uint8_t op;
    uint8_t subop4;
    uint8_t imm4;
    uint8_t rn4;
    uint8_t rt4;
  } T_Type_Mem;

  typedef struct {
    uint8_t op;
    uint8_t cond5;
    int8_t bdisp5;
  } T_Type_BCond;

  typedef struct {
    uint8_t op;
    uint8_t subop6;
    int16_t bdisp6;
  } T_Type_BUnc;

  typedef struct {
    uint8_t op;
    uint16_t pad7;
  } T_Type_Halt;

  typedef struct {
    bool valid;
    void* end_rot;
    unsigned id;
    union {
      T_Type_Imm8 F_Type_Imm8;
      T_Type_Alu3 F_Type_Alu3;
      T_Type_Alu2 F_Type_Alu2;
      T_Type_Mem F_Type_Mem;
      T_Type_BCond F_Type_BCond;
      T_Type_BUnc F_Type_BUnc;
      T_Type_Halt F_Type_Halt;
    };
  } DecCacheItem ;

public:

  bool has_delayed_load;
  char* delayed_load_program;
  stm32_parms::stm32_isa ISA;
  //!Address of Interpretation Routines.
  void** IntRoutine;

  DecCacheItem* DEC_CACHE;
  DecCacheItem* instr_dec;
  bool start_up;

  //!Dispatch Method.
  inline __attribute__((always_inline)) void* dispatch();

  //!Behavior execution method.
  void behavior();

  SC_HAS_PROCESS( stm32 );

  sc_event wake;

  //!Constructor.
  stm32( sc_module_name name_ ): ac_module(name_), stm32_arch(), ISA(*this) {
    SC_THREAD( behavior );
    sensitive << wake;
    has_delayed_load = false; 
    start_up=1;
    ac_id.write(globalId++);
  }

  void init_dec_cache() {
    DEC_CACHE = (DecCacheItem*) calloc(sizeof(DecCacheItem), (dec_cache_size / 2));
  }

  unsigned get_ac_pc();

  void set_ac_pc( unsigned int value );

  virtual void PrintStat();

  void init(int ac, char* av[]);

  void init();

  void set_prog_args();

  void load(char* program);

  void delayed_load(char* program);

  void stop(int status = 0);

  virtual ~stm32() {};

};
#endif  //_STM32_H

